package local.lito381.server;
import java.nio.file.*;import java.util.*;
public class ConfigurationRegression {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static void fails(Runnable r,String label){try{r.run();throw new AssertionError(label);}catch(IllegalArgumentException expected){}}
 static void write(Path p,Properties v)throws Exception {try(var out=Files.newBufferedWriter(p,java.nio.charset.StandardCharsets.UTF_8)){v.store(out,"temporary config regression");}}
 public static void main(String[] a)throws Exception {
  Path source=Path.of(a[0]).toAbsolutePath(),root=Path.of(a[1]);Files.createDirectories(root);var input=UnifiedConfiguration.raw(source);UnifiedConfiguration.validate(input);
  var c=ServerConfig.load(source,"standard");check(c.databaseReadOnly()&&!c.statePersistenceEnabled()&&c.ephemeralSourceProfiles(),"fixed readonly memory policy");
  check(c.classicServerIds().equals(List.of(1,2,3))&&c.legacySourceDatabases().equals(List.of("380_ac","380_ac_1","380_ac_2")),"SQL enabled rows exactly");
  check(c.legacySourceWeightRates().equals(List.of(100.0,100.0,100.0)),"one multiplier for all sources");
  check(c.legacySqlProperties().equals(source),"credentials in single canonical file");
  try(var all=AccountRepository.open(c)){all.healthCheck();for(String name:c.classicServerNames()){var repo=(LegacyMySqlRepository)all.repositoryForClassicSource(name);check((double)LiveBattleStats.get(repo,"serverWeightRate")==100.0,"weight wired to repository");check(repo.tournamentProfiles().authoritative(),"source read connected");}}
  var changed=new Properties();changed.putAll(input);Map<String,String> overrides=Map.ofEntries(Map.entry("port","33000"),Map.entry("server.name","ConfigProbe"),Map.entry("weight.rate","2.5"),Map.entry("battle.ai.enabled","true"),Map.entry("battle.physical.hit.enabled","false"),Map.entry("battle.natural.mp.regen.enabled","false"),Map.entry("native.siege.roster.enforced","false"),Map.entry("native.tournament.allowance","54321"),Map.entry("administration.accounts","ConfigAdmin"),Map.entry("memory.initial","256m"),Map.entry("memory.maximum","1g"),Map.entry("cpu.limit","2"),Map.entry("startup.timeout.seconds","15"));overrides.forEach(changed::setProperty);Path variant=root.resolve("variant.properties");write(variant,changed);
  try{var v=ServerConfig.load(variant,"standard");check(v.port()==33000&&v.advertisedPort()==33000,"single port derived");check(v.serverName().equals("ConfigProbe")&&v.originSourceName().equals("ConfigProbe"),"name derived");check(v.legacySourceWeightRates().equals(List.of(2.5,2.5,2.5)),"multiplier override applied to all sources");check(v.battleAiEnabled()&&!v.battlePhysicalHitEnabled()&&!v.battleNaturalMpRegenEnabled()&&!v.nativeSiegeRosterEnforced(),"all game toggles affect config");check(v.nativeTournamentAllowance()==54321&&v.administrationAccounts().contains("configadmin"),"allowance/admin wired");check(SharedDatabase.properties(variant).getProperty("login.source.port.base").equals("33000"),"SourceLogin uses unified base port");try(var all=AccountRepository.open(v)){for(String name:v.classicServerNames()){var repo=(LegacyMySqlRepository)all.repositoryForClassicSource(name);check((double)LiveBattleStats.get(repo,"serverWeightRate")==2.5,"modified multiplier reaches actual repository");}}}finally{Files.delete(variant);}
  var sources=List.of(new UnifiedConfiguration.Source(1,"A","a",true),new UnifiedConfiguration.Source(2,"B",null,false),new UnifiedConfiguration.Source(8,"H","h",true));UnifiedConfiguration.validateSources(sources);
  fails(()->UnifiedConfiguration.validateSources(List.of(new UnifiedConfiguration.Source(1,"A","a",false))),"all disabled");
  fails(()->UnifiedConfiguration.validateSources(List.of(new UnifiedConfiguration.Source(9,"A","a",true))),"ninth source");
  fails(()->UnifiedConfiguration.validateSources(List.of(new UnifiedConfiguration.Source(1,"A","a",true),new UnifiedConfiguration.Source(2,"a","b",true))),"duplicate name");
  fails(()->UnifiedConfiguration.validateSources(List.of(new UnifiedConfiguration.Source(1,"A","a",true),new UnifiedConfiguration.Source(2,"B","A",true))),"duplicate database");
  for(var invalid:Map.of("weight.rate","NaN","database.read.only","false","battle.ai.enabled","yes","memory.initial","9999g","native.tournament.allowance","1000001","unknown.setting","1").entrySet()){var bad=new Properties();bad.putAll(input);bad.setProperty(invalid.getKey(),invalid.getValue());fails(()->UnifiedConfiguration.validate(bad),"bad setting "+invalid.getKey());}
  Path dup=root.resolve("duplicate.properties");Files.writeString(dup,"weight.rate=1\nweight.rate=2\n");try{try{UnifiedConfiguration.raw(dup);throw new AssertionError("duplicate accepted");}catch(IllegalArgumentException expected){}}finally{Files.delete(dup);}
  Path overlay=root.resolve("overlay.properties");Files.writeString(overlay,"configuration.base.file="+source.toString().replace('\\','/')+"\ncapture.directory="+root.toAbsolutePath().resolve("isolated-captures").toString().replace('\\','/')+"\n");try{var o=ServerConfig.load(overlay,"standard");check(o.legacySqlProperties().equals(source)&&o.classicServerIds().equals(c.classicServerIds()),"secret-free runtime overlay uses canonical config");check(o.captureDirectory().endsWith("isolated-captures"),"per-run capture override");}finally{Files.delete(overlay);}
  System.out.println("PASS SQL directory and aliases; 3 active/8 stable slots; all game config switches; actual repository weight override; fixed policy; JVM/range validation; unknown/duplicate keys fail closed; secret-free overlay");
 }
}
